import java.util.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class SoftAssert {
    private final List<String> fails = new ArrayList<>();

    void checkEquals(Object expected, Object actual, String msg) {
        if (!Objects.equals(expected, actual)) fails.add(msg);
    }

    void checkTrue(boolean cond, String msg) {
        if (!cond) fails.add(msg);
    }

    void assertAll() {
        if (!fails.isEmpty()) throw new AssertionError(String.join("; ", fails));
    }
}

public class SoftAssertTest {
    @Test
    void passesWhenAllOk() {
        SoftAssert s = new SoftAssert();
        s.checkEquals(1, 1, "one");
        s.checkTrue(true, "flag");
        s.assertAll();
    }

    @Test
    void collectsMultiple() {
        SoftAssert s = new SoftAssert();
        s.checkEquals("a", "b", "eq");
        s.checkTrue(false, "flag");
        AssertionError err = assertThrows(AssertionError.class, s::assertAll);
        assertTrue(err.getMessage().contains("eq"));
        assertTrue(err.getMessage().contains("flag"));
    }
}
